/** Every event type: the shape of its `data`. */
export interface Events {
  /** The reply, complete; repairs any delta a client dropped. */
  "assistant.completed": {
    messageId?: string
    ref?: number
    content: string
    reasoning?: string
    lengthStopped: boolean
    stepsTruncated: boolean
    usage?: Usage
  }
  /** Streamed reply text. */
  "assistant.delta": {
    text: string
    partId: string
    /** Byte offset into the part; a gap means a delta was dropped. */
    offset: number
  }
  /** The tail of the reply so far, at most every 2 s, for narration subscriptions. */
  "assistant.narration": {
    partId: string
    tail: string
    /** Byte offset into the part where the tail starts; the next delta continues at offset + its byte length. */
    offset?: number
  }
  /** A background session settled; bg.output reads its answer, bg.inject sends it to a session. */
  "bg.completed": BackgroundSession
  /** A background session started, or one an earlier server or TUI left running was re-adopted. */
  "bg.started": BackgroundSession
  /** A background session's status changed (running, stalled, …). */
  "bg.status": {
    bgId: string
    status: string
    previous: string
  }
  /** The history was compacted before a turn. */
  "compaction.completed": {
    kind: "llm" | "heuristic" | "truncate"
    before: number
    after: number
    savedPct?: number
  }
  /** A transcript row was added: the prompt, a notice, a summary. */
  "message.created": {
    messageId: string
    ref?: number
    role: string
    kind?: string
    content: string
    createdAt?: number
  }
  /** A question was put for a client to answer: permission.requested with its sessionId, for every client, following the session or not — and a background session's relayed question, named by its background id and answered the same way. A third shape joins the arm: a project-trust prompt (kind "trust") discovered by a context.sources measurement, answered by `context.trust` and not by `permission.respond`. */
  "permission.asked": {
    askId: string
    toolCallId: string
    tool: string
    arguments: Record<string, unknown>
    reason?: string
    /** `gate`, `hook:<names>`, or `tool:<name>` for a question the call puts itself (`AskUser`, `PlanExit`) */
    source?: string
    mode?: string
    options: ("once" | "always" | "reject")[]
    alwaysScope?: Record<string, string>
    /** C-SEC-2.b: server-computed unified diff of the proposed call, confined to the session root and capped at 32 KiB (beyond it, an omitted note naming the change size, never silence); absent when the call has no previewable outcome. Has real file line numbers, unlike a client-minted snippet diff. */
    diff?: string
    /** The delegated run that asked, when a sub-agent's question was relayed; absent for the turn's own. */
    origin?: {
      agentId: string
      agentName?: string
      parentCallId?: string
    }
    sessionId: SessionId
  } | {
    askId: string
    /** WEB-3b: the marker that makes a `permission.asked` payload a project-trust prompt — answered by `context.trust`; `permission.respond` never sees these (they are not in the turn's question registry). */
    kind: "trust"
    /** C-SEC-5.b: which grant door this prompt is about — the project `.mcp.json` census verdict (`mcp`), a drifted MCP command needing re-approval (`mcp-pin`, which answers through the same list), lifecycle hooks, `` !`cmd` `` command shell forms, or the project settings layer. A grant lands the root in that door's `trustedProject*` list (see the census in `Bootstrap::pendingProjectTrust`). */
    target: "mcp" | "mcp-pin" | "hooks" | "commands" | "settings"
    /** The project root the prompt is about — the exact string the grant writes into that door's trusted list. */
    root: string
    /** Why the prompt was put, for the panel line. */
    reason?: string
    /** `asked` while open; one answer settles it for the process (the once-per-(root, target) law — the other targets' prompts stay open beside it). */
    status: "asked" | "granted" | "rejected"
    /** True when the answer wrote the user-tier trust list; a session grant or a refusal leaves it false. */
    persisted?: boolean
    sessionId: SessionId
  }
  /** A tool call is waiting for an answer (permission.respond). */
  "permission.requested": PendingAsk
  /** A question was answered or cancelled. */
  "permission.resolved": {
    askId: string
    reply?: "once" | "always" | "reject"
    note?: string
    cancelled?: boolean
  }
  /** A question was answered or cancelled (permission.resolved for every client) — a background session's relayed question included, cancelled when its session settled unanswered. */
  "permission.settled": {
    sessionId: SessionId
    askId: string
    reply?: "once" | "always" | "reject"
    cancelled?: boolean
  }
  /** Streamed reasoning text. */
  "reasoning.delta": {
    text: string
    partId: string
    /** Byte offset into the part; a gap means a delta was dropped. */
    offset: number
  }
  /** This client fell behind; ephemeral events were dropped — resubscribe. */
  "server.overflow": {
    dropped: number
    action: "resubscribe"
  }
  /** The server is stopping. */
  "server.shutdown": {
    reason: string
    graceSeconds: number
  }
  /** Liveness, every tickIntervalMs. */
  "server.tick": {
    now: number
    turnsRunning: number
  }
  /** A session was created. */
  "session.created": SessionSummary
  /** A session was deleted. */
  "session.deleted": {
    id: SessionId
  }
  /** The session became idle, busy or waiting_permission. */
  "session.status": {
    status: "idle" | "busy" | "waiting_permission"
  }
  /** A session was renamed, its mode changed, its model changed, or its status changed (idle, busy, waiting_permission). A served `/model` or `/rename` reaches every client through this arm, not only the status lane. */
  "session.updated": SessionSummary
  /** The session spend cap stopped the turn. */
  "spend_cap.breached": {
    calls: number
    spent: number
    cap: number
  }
  /** A delegated sub-agent finished. */
  "subagent.finished": {
    v?: number
    id: string
    op: string
    name?: string | null
    /** The delegated prompt; carried on started only. */
    task?: string | null
    seq?: number
    tail?: unknown
    tokens?: number
    cost?: number
    lines?: number
    model?: string
    context?: number
    calls?: {
      id: string
      label: string
      state: string
      at?: number
    }[]
    parentCallId?: string | null
    parentAgentId?: string | null
    description?: string
    items?: Record<string, unknown>[]
    stats?: Record<string, number>
    outcome?: unknown
    error?: string | null
    resumeId?: string | null
    transcriptLog?: string | null
    parentSessionId?: string | null
    childSessionId?: string | null
  }
  /** A delegated sub-agent made progress. */
  "subagent.progress": {
    v?: number
    id: string
    op: string
    name?: string | null
    /** The delegated prompt; carried on started only. */
    task?: string | null
    seq?: number
    tail?: unknown
    tokens?: number
    cost?: number
    lines?: number
    model?: string
    context?: number
    calls?: {
      id: string
      label: string
      state: string
      at?: number
    }[]
    parentCallId?: string | null
    parentAgentId?: string | null
    description?: string
    items?: Record<string, unknown>[]
    stats?: Record<string, number>
    outcome?: unknown
    error?: string | null
    resumeId?: string | null
    transcriptLog?: string | null
    parentSessionId?: string | null
    childSessionId?: string | null
  }
  /** A delegated sub-agent started. */
  "subagent.started": {
    v?: number
    id: string
    op: string
    name?: string | null
    /** The delegated prompt; carried on started only. */
    task?: string | null
    seq?: number
    tail?: unknown
    tokens?: number
    cost?: number
    lines?: number
    model?: string
    context?: number
    calls?: {
      id: string
      label: string
      state: string
      at?: number
    }[]
    parentCallId?: string | null
    parentAgentId?: string | null
    description?: string
    items?: Record<string, unknown>[]
    stats?: Record<string, number>
    outcome?: unknown
    error?: string | null
    resumeId?: string | null
    transcriptLog?: string | null
    parentSessionId?: string | null
    childSessionId?: string | null
  }
  /** A Todo call rewrote the session's todo list; carries the whole list. */
  "todo.updated": {
    toolCallId?: string
    items: ({
      content: string
      status: "pending" | "in_progress" | "completed" | "cancelled"
    })[]
  }
  /** A tool call finished (content capped; tool.output has the rest). */
  "tool.finished": {
    messageId?: string
    ref?: number
    toolCallId: string
    name: string
    isError: boolean
    durationMs?: number
    /** At most 256 KiB; tool.output reads the rest. */
    content: string
    truncated?: boolean
    diff?: string
    denial?: {
      kind: string
      reason?: string
    }
    /** Artifact refs from the session media store — paths only, never bytes (Appendix C-7). */
    media?: MediaRef[]
    mediaTruncated?: boolean
    replaces?: string
  }
  /** Live tail of a running tool call, frame-rate capped; ephemeral — tool.finished is the contract, so a late joiner replays nothing and still sees the whole output. */
  "tool.progress": {
    toolCallId: string
    name: string
    /** Frames of this call so far, from 1; a client keeps the highest it has seen. */
    seq: number
    /** The last tailBudget bytes of output, replaced wholesale each frame — never a delta to stitch. */
    tail: string
    /** True once bytes fell out of the ring. */
    truncated: boolean
    /** Byte cap the tail obeys. */
    tailBudget: number
  }
  /** A tool call started. */
  "tool.started": {
    messageId?: string
    ref?: number
    toolCallId: string
    name: string
    arguments?: Record<string, unknown>
  }
  /** A turn ended, with its stopReason. */
  "turn.completed": {
    stopReason: "end_turn" | "max_steps" | "length" | "cancelled" | "spend_cap" | "loop_guard" | "error"
    error?: string
    messageId?: string
  }
  /** A queued prompt left the queue (sent or removed). */
  "turn.dequeued": {
    queueId: string
    text?: string
    reason: "sent" | "removed"
  }
  /** A prompt was queued behind the running turn. */
  "turn.queued": {
    queueId: string
    text: string
    position: number
  }
  /** A turn began. */
  "turn.started": {
    turnId: string
    messageId?: string
  }
  /** A steering message was handed to the running turn. */
  "turn.steered": {
    turnId?: string
    steerId: string
  }
  /** The running turn reached a step boundary. */
  "turn.step": {
    step: number
    maxSteps: number
    context?: Record<string, unknown> | null
  }
  /** Token and cost usage changed. */
  "usage.updated": {
    step: number
    usage?: Usage | null
    turnUsage?: Usage | null
  }
}

export type EventName = keyof Events

/** Whether each event type is durable (logged, carries a `seq`) and its scope. */
export const EVENT_KINDS: { readonly [E in EventName]: { readonly durable: boolean; readonly scope: 'session' | 'server' } } = {
  "assistant.completed": { durable: true, scope: "session" },
  "assistant.delta": { durable: false, scope: "session" },
  "assistant.narration": { durable: false, scope: "session" },
  "bg.completed": { durable: false, scope: "server" },
  "bg.started": { durable: false, scope: "server" },
  "bg.status": { durable: false, scope: "server" },
  "compaction.completed": { durable: true, scope: "session" },
  "message.created": { durable: true, scope: "session" },
  "permission.asked": { durable: false, scope: "server" },
  "permission.requested": { durable: true, scope: "session" },
  "permission.resolved": { durable: true, scope: "session" },
  "permission.settled": { durable: false, scope: "server" },
  "reasoning.delta": { durable: false, scope: "session" },
  "server.overflow": { durable: false, scope: "server" },
  "server.shutdown": { durable: false, scope: "server" },
  "server.tick": { durable: false, scope: "server" },
  "session.created": { durable: false, scope: "server" },
  "session.deleted": { durable: false, scope: "server" },
  "session.status": { durable: true, scope: "session" },
  "session.updated": { durable: false, scope: "server" },
  "spend_cap.breached": { durable: true, scope: "session" },
  "subagent.finished": { durable: true, scope: "session" },
  "subagent.progress": { durable: false, scope: "session" },
  "subagent.started": { durable: true, scope: "session" },
  "todo.updated": { durable: true, scope: "session" },
  "tool.finished": { durable: true, scope: "session" },
  "tool.progress": { durable: false, scope: "session" },
  "tool.started": { durable: true, scope: "session" },
  "turn.completed": { durable: true, scope: "session" },
  "turn.dequeued": { durable: true, scope: "session" },
  "turn.queued": { durable: true, scope: "session" },
  "turn.started": { durable: true, scope: "session" },
  "turn.steered": { durable: true, scope: "session" },
  "turn.step": { durable: false, scope: "session" },
  "usage.updated": { durable: true, scope: "session" },
}
